WITH base AS (SELECT *, CONCAT_WS('-', method, status) AS method_status_key, COALESCE(method, 'N/A') AS method_filled FROM payments WHERE paid_at > DATE '2023-11-19' AND order_id IS NOT NULL AND amount >= 550), prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) AS prev_paid_at FROM base), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN amount >= 1330 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, MIN(session_start_flag) AS min_session_start_flag, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, (UNIX_TIMESTAMP(MAX(prev_paid_at)) - UNIX_TIMESTAMP(MIN(prev_paid_at))) / 60 AS duration_min_2 FROM sessions_payments GROUP BY CASE WHEN amount >= 1330 THEN 'LARGE' ELSE 'SMALL' END HAVING MIN(session_start_flag) >= 0
